"""Extract the dialogue of a Claude Code session transcript as Markdown.

Keeps the user's messages (including those sent while Claude was working and the
answers to Claude's questions), Claude's visible replies, and one line per turn
summarising Claude's tool use. Drops thinking, tool inputs and outputs, system
context, subagent hand-backs and compaction summaries. Masks the account email
(read from the transcript itself) and the local user name.

usage: python3 -I extract.py TRANSCRIPT.jsonl OUT.md TITLE
"""

import collections
import json
import re
import sys

src, out, title = sys.argv[1], sys.argv[2], sys.argv[3]
records = [json.loads(line) for line in open(src, encoding="utf-8") if line.strip()]

email = None
for r in records:
    ctx = (r.get("attachment") or {}).get("context") or {}
    m = re.search(r"email address is (\S+?)\.\s", ctx.get("userEmail", ""))
    if m:
        email = m.group(1)
        break


def mask(text: str) -> str:
    if email:
        text = re.sub(re.escape(email), "<masked-email>", text, flags=re.I)
    return re.sub(r"\b<user>\b", "<user>", text)


def is_foreign(text: str) -> bool:
    """Messages that look like user input but come from subagents or the harness."""
    t = text.lstrip()
    return (
        t.startswith("<task-notification>")
        or "<agent-message from=" in t
        or t.startswith("Another Claude session sent a message")
        or t.startswith("This session is being continued from a previous conversation")
        or t.startswith("<local-command-caveat>")
    )


def clean_user(text: str) -> str:
    text = re.sub(r"<system-reminder>.*?</system-reminder>", "", text, flags=re.S)
    text = re.sub(r"<local-command-caveat>.*?</local-command-caveat>", "", text, flags=re.S)
    cmd = re.search(r"<command-name>(.*?)</command-name>", text, flags=re.S)
    if cmd:
        args = re.search(r"<command-args>(.*?)</command-args>", text, flags=re.S)
        a = args.group(1).strip() if args else ""
        text = f"`{cmd.group(1).strip()}{' ' + a if a else ''}` (slash command)"
    text = re.sub(
        r"<local-command-stdout>(.*?)</local-command-stdout>",
        lambda m: f"_(command output: {m.group(1).strip()})_",
        text,
        flags=re.S,
    )

    def pasted(m: re.Match) -> str:
        body = m.group(1).strip("\n")
