"""Copy the raw Claude Code transcripts into ai-logs/raw with masking only.

Masks the account email (read from the transcripts themselves, so nobody has to type it)
and the local user name wherever it stands as a word. Every other byte is copied as is.
Re-run it after the last session has ended to refresh the controller transcript.

usage: python3 -I export_raw.py
"""

import json
import re
import shutil
from pathlib import Path

REPO = Path.home() / "Development/taxdome/ta-firm-payments-challenge"
PROJECTS = Path.home() / ".claude/projects"
USER = Path.home().name
DST = REPO / "ai-logs/raw"


def folder(repo: Path) -> Path:
    """Return Claude Code's transcript folder for a working directory."""
    return PROJECTS / str(repo).replace("/", "-")


SESSIONS = {
    folder(REPO): [
        "11e93ff2-e87d-4343-8a93-48e52280be77",  # setup: plugins, login
        "6c475ff3-2d78-4f48-a57e-d3bfff1c6542",  # setup: plugins
        "dd5c182d-e57e-490d-98db-cb517e4b9648",  # setup: /model, /effort
        "34fb75aa-e848-4899-b380-313c497e2654",  # controller, with subagents
    ],
    folder(REPO.parent / "ta-firm-payments-review"): [
        "a81e543f-a226-42f0-8cc1-88cfc8a1baeb",  # independent review
    ],
}


def find_email() -> str:
    """Read the account email from the session context recorded in a transcript."""
    for src, ids in SESSIONS.items():
        for sid in ids:
            for line in (src / f"{sid}.jsonl").open(encoding="utf-8"):
                if "userEmail" not in line:
                    continue
                ctx = (json.loads(line).get("attachment") or {}).get("context") or {}
                m = re.search(r"email address is (\S+?)\.\s", ctx.get("userEmail", ""))
                if m:
                    return m.group(1)
    raise SystemExit("account email not found in the transcripts")


def main() -> None:
    """Copy and mask every listed session, then check that nothing is left unmasked."""
    email = find_email()
    email_re = re.compile(re.escape(email), re.IGNORECASE)
    user_re = re.compile(rf"\b{re.escape(USER)}\b")
    if DST.exists():
        shutil.rmtree(DST)
    for src, ids in SESSIONS.items():
        for sid in ids:
            paths = [src / f"{sid}.jsonl"]
            if (src / sid).is_dir():
                paths += [p for p in sorted((src / sid).rglob("*")) if p.is_file()]
            for p in paths:
                out = DST / p.relative_to(src)
                out.parent.mkdir(parents=True, exist_ok=True)
                try:
                    text = p.read_text(encoding="utf-8")
                except UnicodeDecodeError:
                    shutil.copy2(p, out)
                    continue
                out.write_text(user_re.sub("<user>", email_re.sub("<masked-email>", text)), encoding="utf-8")
    left = [
        str(p.relative_to(DST))
        for p in DST.rglob("*")
        if p.is_file() and (email.lower() in (t := p.read_bytes().decode("utf-8", "replace")).lower() or user_re.search(t))
    ]
    size = sum(p.stat().st_size for p in DST.rglob("*") if p.is_file())
    count = sum(1 for p in DST.rglob("*") if p.is_file())
    print(f"{count} files, {size / 1e6:.1f} MB in {DST}; unmasked files: {left or 'none'}")


main()

