    local, domain = email.split("@", 1)
    parts = [email, local, domain, domain.split(".")[0]]
    parts += [t for t in re.split(r"[^A-Za-z0-9]+", local) if len(t) > 3 and t.lower() != "claude"]
    email_re = re.compile("|".join(re.escape(x) for x in parts), re.IGNORECASE)
    # The user name anywhere it is not the start of a longer name (keeps the GitHub owner).
    user_re = re.compile(re.escape(USER) + r"(?![A-Za-z0-9])")
    if DST.exists():
        shutil.rmtree(DST)
    for src, ids in SESSIONS.items():
        for sid in ids:
            paths = [src / f"{sid}.jsonl"]
            if (src / sid).is_dir():
                paths += [p for p in sorted((src / sid).rglob("*")) if p.is_file()]
            for p in paths:
                out = DST / p.relative_to(src)
                out.parent.mkdir(parents=True, exist_ok=True)
                try:
                    text = p.read_text(encoding="utf-8")
                except UnicodeDecodeError:
                    shutil.copy2(p, out)
                    continue
                out.write_text(
                    user_re.sub("<user>", email_re.sub("<masked-email>", text)), encoding="utf-8"
                )
    left = [
        str(p.relative_to(DST))
        for p in DST.rglob("*")
        if p.is_file()
        and (
            email.lower() in (t := p.read_bytes().decode("utf-8", "replace")).lower()
            or user_re.search(t)
        )
    ]
    size = sum(p.stat().st_size for p in DST.rglob("*") if p.is_file())
    count = sum(1 for p in DST.rglob("*") if p.is_file())
    print(f"{count} files, {size / 1e6:.1f} MB in {DST}; unmasked files: {left or 'none'}")


main()

